/**
 * This function was copied from the creators of ModuleFederation which is why a few things in it are a bit
 * weird.
 *
 * It loads a Module wrapped up by Module federation. It returns a callback function. When you call it, it returns
 * a Promise that resolves to the Module it is loading.
 * @param remote - Syncs up with ModuleFederation 'name'.
 * @param sharedScope - Just pass in the string 'default'
 * @param moduleName - Syncs up with ModuleFederation 'exposes'
 * @param url - Normally remoteEntry.js
 * @returns A callback function to initialize the loading.
 * The Module that is resolved should have module.default.psMfeInit and then you can call that to
 * bootstrap the MFE.
 */
export declare const loadComponent: (remote: string, sharedScope: any, moduleName: string, url: string, throwErrors?: boolean) => any;
